// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(
    Object.entries(q ?? {})
      .filter(([, v]) => v !== undefined && v !== null)
      .map(([k, v]) => [k, String(v)]),
  ).toString();
  return s ? `${path}?${s}` : path;
};

/** An approval request (service.APPROVAL_COLS). */
export interface ApprovalOut {
  request_id: number;
  approval_type:
    | "Refund"
    | "VIPWaiverPreConsult"
    | "VIPWaiverPostConsult"
    | "PatientCredit"
    | "PharmacyCharityOverride"
    | "LargeCashDrop"
    | "WardIndent"
    | "APPayment"
    | "PolicyChange"
    | "PrivilegedAccess";
  /** Who may decide: every holder of this permission sees the request */
  required_permission: string;
  requester_id: number;
  requester_name: string;
  subject_type: string;
  subject_id: number;
  patient_id: number | null;
  amount: number | null;
  summary: string;
  /** Type-specific details the approver needs to decide */
  payload_jsonb: Record<string, unknown>;
  /** Needs the elevated approver (e.g. a large refund) */
  is_elevated: boolean;
  status: "Pending" | "Approved" | "Rejected" | "Cancelled";
  decided_by: number | null;
  decided_by_name: string | null;
  decided_at: string | null;
  decision_note: string | null;
  /** Decided by its own requester, the Owner of a solo practice (audit H-5); a risk item records it */
  solo_self_approved: boolean;
  requested_at: string;
}

export interface DecisionIn {
  /** Required when rejecting */
  note?: string | null;
  /** Dual control: co-signer username (large cash) */
  second_approver_username?: string | null;
  /** Dual control: co-signer password */
  second_approver_password?: string | null;
  /** Ward indent partial approval: [{"ward_indent_item_id": 1, "qty_approved": 5}] */
  items?: Record<string, unknown>[] | null;
}

/** The request after an approve / reject / cancel, with the effect applied in the same transaction. */
export interface ApprovalDecisionOut {
  request_id: number;
  approval_type:
    | "Refund"
    | "VIPWaiverPreConsult"
    | "VIPWaiverPostConsult"
    | "PatientCredit"
    | "PharmacyCharityOverride"
    | "LargeCashDrop"
    | "WardIndent"
    | "APPayment"
    | "PolicyChange"
    | "PrivilegedAccess";
  /** Who may decide: every holder of this permission sees the request */
  required_permission: string;
  requester_id: number;
  requester_name: string;
  subject_type: string;
  subject_id: number;
  patient_id: number | null;
  amount: number | null;
  summary: string;
  /** Type-specific details the approver needs to decide */
  payload_jsonb: Record<string, unknown>;
  /** Needs the elevated approver (e.g. a large refund) */
  is_elevated: boolean;
  status: "Pending" | "Approved" | "Rejected" | "Cancelled";
  decided_by: number | null;
  decided_by_name: string | null;
  decided_at: string | null;
  decision_note: string | null;
  /** Decided by its own requester, the Owner of a solo practice (audit H-5); a risk item records it */
  solo_self_approved: boolean;
  requested_at: string;
  effect: ApprovalEffectOut;
}

/** What the decision did. Only the fields of the request's approval type are present. */
export interface ApprovalEffectOut {
  /** Refund approved: the cash-out to hand over */
  refund_disbursement_id?: number | null;
  /** Refund approved: its amount */
  amount?: number | null;
  /** Refund not approved */
  refund?: "not approved" | null;
  /** Waiver approved */
  waiver_amount?: number | null;
  /** Post-consultation waiver: cash to hand back */
  cash_back_order?: WaiverRefundOrderOut | null;
  /** Waiver not approved */
  waiver?: "not approved" | null;
  /** Credit approved */
  credit_amount?: number | null;
  /** Credit not authorized */
  credit?: "not authorized" | null;
  /** Pharmacy charity override */
  charity_override?: "approved" | "rejected" | "cancelled" | null;
  /** Large cash drop */
  cash_drop?: "approved" | "rejected" | null;
  /** AP payment (not approved: the payable is cancelled) */
  payable?: "approved" | "cancelled" | null;
  /** Ward indent */
  indent?: "approved" | "rejected" | "cancelled" | null;
  /** Ward indent approved with less than requested */
  partial?: boolean | null;
  /** Policy or privileged-access change request */
  change_request?: "Applied" | "Rejected" | "Cancelled" | null;
}

/** Cash to hand back after an approved post-consultation waiver (reception confirms the dispensation). */
export interface WaiverRefundOrderOut {
  waiver_refund_order_id: number;
  waiver_request_id: number;
  ticket_id: number;
  refund_amount: number;
  status: "PendingDispensation" | "Dispensed" | "Cancelled";
  shift_id: number | null;
  dispensed_by: number | null;
  dispensed_at: string | null;
  row_version: number;
}

/** Approval queue visible to me (or my own requests with mine=true) — GET /api/v1/approvals (permissions: any logged-in user). */
export function listApprovals(query?: {
  status?: "Pending" | "Approved" | "Rejected" | "Cancelled";
  mine?: boolean;
  limit?: number;
}): Promise<ApprovalOut[]> {
  return api<ApprovalOut[]>("GET", withQuery(`/approvals`, query), undefined);
}

/** One approval request — GET /api/v1/approvals/{request_id} (permissions: any logged-in user). */
export function getApproval(request_id: number): Promise<ApprovalOut> {
  return api<ApprovalOut>("GET", `/approvals/${request_id}`, undefined);
}

/** Approve (applies the effect atomically) — POST /api/v1/approvals/{request_id}/approve (permissions: any logged-in user). */
export function approve(
  request_id: number,
  body: DecisionIn,
): Promise<ApprovalDecisionOut> {
  return api<ApprovalDecisionOut>(
    "POST",
    `/approvals/${request_id}/approve`,
    body,
  );
}

/** Reject (unfreezes the subject) — POST /api/v1/approvals/{request_id}/reject (permissions: any logged-in user). */
export function reject(
  request_id: number,
  body: DecisionIn,
): Promise<ApprovalDecisionOut> {
  return api<ApprovalDecisionOut>(
    "POST",
    `/approvals/${request_id}/reject`,
    body,
  );
}
